import './photo-instance-import.mjs';
const by=id=>document.getElementById(id),api=()=>globalThis.coexLayerLayout;
const panel=document.createElement('details');panel.id='instanceBoundaryPanel';panel.innerHTML=`<summary>분리 경계 다듬기</summary><p class="layer-help">분리된 그림 하나를 선택하세요. 확대해 다른 물체의 잔여물을 지우거나 원본 픽셀을 되살립니다. 가려진 뒷면은 생성 보완이 필요합니다.</p><button type="button" class="doc-btn" id="boundaryOpen">선택 그림의 경계 열기</button><div id="boundaryTools" hidden><label>브러시 <select id="boundaryMode"><option value="erase">불필요한 부분 지우기</option><option value="restore">원본 픽셀 되살리기</option></select></label><label>굵기 · 원본 px <input id="boundarySize" type="range" min="2" max="80" value="12"></label><label>확대 <select id="boundaryZoom"><option value="fit">화면에 맞춤</option><option value="1">100%</option><option value="2">200%</option></select></label><label>검사 배경 <select id="boundaryBackground"><option value="checker">체크무늬</option><option value="white">흰색</option><option value="black">검정</option></select></label><div style="overflow:auto;max-height:460px;border:1px solid #ccc"><canvas id="boundaryCanvas" aria-label="드래그해서 분리 마스크 수정" style="display:block;touch-action:none;cursor:crosshair;background:repeating-conic-gradient(#ddd 0 25%,#fff 0 50%) 0/16px 16px"></canvas></div><button type="button" class="doc-btn" id="boundaryUndo">한 단계 되돌리기</button><button type="button" class="doc-btn" id="boundaryApply">경계 수정 적용</button><button type="button" class="doc-btn" id="boundaryReset">다듬기 전 경계로 복원</button></div><p id="boundaryStatus" class="layer-help" role="status" aria-live="polite"></p>`;
by('photoInstancesPanel').after(panel);let draft=null,stroke=false,last=null,token=0;
const say=t=>by('boundaryStatus').textContent=t;
function selected(){return api()?.read()?.objects.find(o=>o.canvas)?.canvas?.getActiveObject();}
function valid(d){const s=api()?.read();return s&&s.epoch===d.state.epoch&&s.revision===d.state.revision&&s.objects.includes(d.object)&&selected()===d.object;}
async function decode(src){const im=new Image();im.src=src;await im.decode();return im;}
function pixels(el,w,h,x=0,y=0){const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(el,-x,-y);return c.getContext('2d').getImageData(0,0,w,h);}
function render(){if(!draft)return;by('boundaryCanvas').getContext('2d').putImageData(draft.image,0,0);}
function zoom(){if(!draft)return;const c=by('boundaryCanvas'),z=by('boundaryZoom').value;c.style.width=z==='fit'?'100%':draft.image.width*Number(z)+'px';c.style.height='auto';c.style.maxWidth=z==='fit'?draft.image.width+'px':'none';}
by('boundaryZoom').onchange=zoom;
by('boundaryBackground').onchange=()=>{const v=by('boundaryBackground').value;by('boundaryCanvas').style.background=v==='checker'?'repeating-conic-gradient(#ddd 0 25%,#fff 0 50%) 0/16px 16px':v;};
by('boundaryOpen').onclick=async()=>{const id=++token;draft=null;by('boundaryTools').hidden=true;const state=api()?.read(),o=selected(),crop=o?.photoInstanceCrop;
 if(!state||o?.photoInstanceKind!=='part'||!crop){say('먼저 개체별로 분리된 그림 하나를 선택하세요.');return;}
 if(o.generatedMethod){say('생성 전 그림으로 복원한 뒤 경계를 수정하세요.');return;}
 try{const original=state.objects.find(x=>x.photoInstanceGroup===o.photoInstanceGroup&&x.photoInstanceKind==='source');if(!original?.originalPhotoSource)throw Error('보관된 원본 사진을 찾지 못했습니다.');const source=await decode(original.originalPhotoSource);if(id!==token)return;
  const w=o.width,h=o.height,image=pixels(o.getElement(),w,h),rgb=pixels(source,w,h,crop.x,crop.y),blocked=new Uint8Array(w*h);
  for(const other of state.objects)if(other!==o&&other.photoInstanceGroup===o.photoInstanceGroup&&other.photoInstanceKind==='part'&&other.photoInstanceCrop){const b=other.photoInstanceCrop,mask=pixels(other.getElement(),w,h,crop.x-b.x,crop.y-b.y).data;for(let i=0;i<blocked.length;i++)if(mask[i*4+3]>24)blocked[i]=1;}
  const d={state,object:o,image,rgb,blocked,history:[],dirty:false};if(!valid(d))throw Error('선택이 바뀌었습니다. 다시 여세요.');draft=d;const c=by('boundaryCanvas');c.width=w;c.height=h;by('boundaryTools').hidden=false;render();zoom();say('적용 전에는 편집 화면이 바뀌지 않습니다. 되살리기는 현재 그림 범위 안에서만 가능하며 다른 물체가 차지한 영역은 보호합니다.');
 }catch(e){say(e.message);}};
function paint(e){const d=draft;if(!d||!stroke)return;const c=by('boundaryCanvas'),r=c.getBoundingClientRect(),p={x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height},a=last||p,radius=Number(by('boundarySize').value)/2,steps=Math.max(1,Math.ceil(Math.hypot(p.x-a.x,p.y-a.y)/Math.max(1,radius/3))),restore=by('boundaryMode').value==='restore',w=c.width,h=c.height;
 for(let s=0;s<=steps;s++){const cx=a.x+(p.x-a.x)*s/steps,cy=a.y+(p.y-a.y)*s/steps;for(let y=Math.max(0,Math.floor(cy-radius));y<=Math.min(h-1,Math.ceil(cy+radius));y++)for(let x=Math.max(0,Math.floor(cx-radius));x<=Math.min(w-1,Math.ceil(cx+radius));x++){if((x-cx)**2+(y-cy)**2>radius**2)continue;const i=y*w+x,j=i*4;if(restore&&d.blocked[i])continue;if(restore){for(let k=0;k<4;k++)d.image.data[j+k]=d.rgb.data[j+k];}else d.image.data[j+3]=0;}}
 last=p;d.dirty=true;render();}
const c=by('boundaryCanvas');c.onpointerdown=e=>{if(!draft||!valid(draft)){say('선택·편집 상태가 바뀌었습니다. 경계를 다시 여세요.');return;}e.preventDefault();draft.history.push(draft.image.data.slice());if(draft.history.length>Math.max(1,Math.min(8,Math.floor(32000000/draft.image.data.length))))draft.history.shift();stroke=true;last=null;c.setPointerCapture(e.pointerId);paint(e);};c.onpointermove=paint;c.onpointerup=c.onpointercancel=e=>{stroke=false;last=null;if(c.hasPointerCapture(e.pointerId))c.releasePointerCapture(e.pointerId);};
by('boundaryUndo').onclick=()=>{if(!draft?.history.length)return;draft.image.data.set(draft.history.pop());draft.dirty=true;render();};
by('boundaryApply').onclick=async()=>{const d=draft;if(!d||!valid(d)){say('선택 또는 편집 상태가 바뀌었습니다. 경계를 다시 여세요.');return;}let count=0;for(let i=3;i<d.image.data.length;i+=4)if(d.image.data[i]>0)count++;if(!count){say('그림 전체가 지워졌습니다. 되돌린 뒤 다시 적용하세요.');return;}const image=await decode(c.toDataURL('image/png'));if(!valid(d))return;const o=d.object;o.photoBoundaryOriginal=o.photoBoundaryOriginal||o.getSrc();o.setElement(image);o.setCoords();api().commit(d.state.width,d.state.height,{epoch:d.state.epoch,revision:d.state.revision,apply:true});draft=null;by('boundaryTools').hidden=true;say('선택 그림의 경계만 수정했습니다. 다른 그림·텍스트·좌표는 유지됩니다.');};
by('boundaryReset').onclick=async()=>{const d=draft;if(!d||!valid(d)||!d.object.photoBoundaryOriginal){say('적용된 경계 수정이 없습니다. 드래그 수정은 한 단계 되돌리기를 사용하세요.');return;}const im=await decode(d.object.photoBoundaryOriginal);if(!valid(d))return;d.object.setElement(im);delete d.object.photoBoundaryOriginal;api().commit(d.state.width,d.state.height,{epoch:d.state.epoch,revision:d.state.revision,apply:true});draft=null;by('boundaryTools').hidden=true;say('다듬기 전 경계로 복원했습니다.');};
for(const event of ['coex:layer-source','coex:layer-edit'])window.addEventListener(event,()=>{token++;draft=null;stroke=false;by('boundaryTools').hidden=true;});
